// Accepts form or webhook-shaped input, validates the Ad Library link and
// extracts the search context we need later (sort mode decides whether the
// "impression rank" market signal is trustworthy).
const APIFY_ACTOR = 'curious_coder~facebook-ads-library-scraper'; // swap scraper here
const MIN_ADS = 3;
const MAX_ADS = 15;

// n8n's Code sandbox has no URL global, so links are parsed by hand.
const safeDecode = (x) => { try { return decodeURIComponent(x); } catch (e) { return x; } };
const parseUrl = (s) => {
  const m = String(s || '').trim().match(/^(https?):\/\/([^/?#]+)([^?#]*)(\?[^#]*)?/i);
  if (!m) return null;
  const pairs = (m[4] || '').slice(1).split('&').filter(Boolean).map((kv) => {
    const i = kv.indexOf('=');
    return [safeDecode(i === -1 ? kv : kv.slice(0, i)), i === -1 ? '' : safeDecode(kv.slice(i + 1)), kv];
  });
  return {
    origin: `${m[1].toLowerCase()}://${m[2].toLowerCase()}`,
    hostname: m[2].toLowerCase().replace(/:\d+$/, ''),
    pathname: m[3] || '/',
    pairs,
    get: (k) => { const hit = pairs.find((p) => p[0] === k); return hit ? hit[1] : null; },
  };
};

const input = $input.first().json;
const body = input.body || {};
const field = (...keys) => keys.map((k) => input[k] ?? body[k]).find((v) => v !== undefined && v !== null && v !== '');
const raw = String(field('adLibraryUrl', 'Ad Library URL') ?? '').trim();
const brandIn = String(field('brand', 'Brand / competitor name') ?? '').trim();
const preparedBy = String(field('preparedBy', 'Prepared by') ?? '').trim();
let maxAds = parseInt(field('maxAds', 'Ads to analyse (3-15)') ?? 8, 10);
if (!Number.isFinite(maxAds)) maxAds = 8;
maxAds = Math.min(Math.max(maxAds, MIN_ADS), MAX_ADS);

const reject = (reason) => [{ json: { valid: false, error: 'Invalid Facebook Ad Library URL.', reason, receivedUrl: raw } }];

const u = parseUrl(raw);
if (!u) return reject('That is not a web link.');
const host = u.hostname.replace(/^(www|m|web|business)\./, '');
if (host !== 'facebook.com' || !u.pathname.startsWith('/ads/library')) {
  return reject('Expected a facebook.com/ads/library/ link.');
}
const p = u;
const q = (p.get('q') || '').replace(/\+/g, ' ').replace(/^"+|"+$/g, '').trim();
const pageId = p.get('view_all_page_id');
const adId = p.get('id');
// A ?id= link opens one ad; the scraper needs a search or a page to list ads from.
if (adId && !q && !pageId) return reject(`That link opens a single ad (id ${adId}). Paste a search link instead, e.g. https://www.facebook.com/ads/library/?active_status=active&country=IN&q=MySivi&sort_data[mode]=total_impressions`);
if (!q && !pageId) return reject('The link has no search keyword or page id.');

const sortMode = p.get('sort_data[mode]') || '';
const country = (p.get('country') || 'ALL').toUpperCase();

return [{
  json: {
    valid: true,
    adLibraryUrl: raw,
    apifyActor: APIFY_ACTOR,
    maxAds,
    fetchCount: Math.max(10, maxAds + 5), // actor minimum is 10; headroom for dedupe
    country,
    query: q,
    pageId: pageId || null,
    adId: adId || null,
    activeStatus: p.get('active_status') || 'all',
    searchType: p.get('search_type') || '',
    sortMode: sortMode || 'relevance',
    impressionSorted: sortMode === 'total_impressions',
    brand: brandIn || q || (pageId ? `Page ${pageId}` : 'Advertiser'),
    preparedBy,
    runStartedAt: new Date().toISOString(),
  },
}];

// Turns whatever the scraper returned into one clean schema per ad.
// Handles snake_case (curious_coder) and camelCase actor outputs, removes
// exact duplicates, flags shared copy, and decodes the video asset id +
// duration that Meta embeds in the CDN url (that is how we tell 15 ads
// with identical captions apart).
const cfg = $('02 — Validate & Parse URL').first().json;

// n8n's Code sandbox has no URL global, so links are parsed by hand.
const safeDecode = (x) => { try { return decodeURIComponent(x); } catch (e) { return x; } };
const parseUrl = (s) => {
  const m = String(s || '').trim().match(/^(https?):\/\/([^/?#]+)([^?#]*)(\?[^#]*)?/i);
  if (!m) return null;
  const pairs = (m[4] || '').slice(1).split('&').filter(Boolean).map((kv) => {
    const i = kv.indexOf('=');
    return [safeDecode(i === -1 ? kv : kv.slice(0, i)), i === -1 ? '' : safeDecode(kv.slice(i + 1)), kv];
  });
  return {
    origin: `${m[1].toLowerCase()}://${m[2].toLowerCase()}`,
    hostname: m[2].toLowerCase().replace(/:\d+$/, ''),
    pathname: m[3] || '/',
    pairs,
    get: (k) => { const hit = pairs.find((p) => p[0] === k); return hit ? hit[1] : null; },
  };
};

const ZW = /[​-‍﻿]/g;
const decodeEntities = (s) => s
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const clean = (v) => {
  if (v == null) return '';
  if (typeof v === 'object') v = v.text ?? '';
  return decodeEntities(String(v))
    .replace(/<[^>]+>/g, ' ')
    .replace(ZW, '')
    .replace(/�/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s*\n\s*/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};
const isTemplate = (s) => /\{\{\s*[\w.]+\s*\}\}/.test(String(s || ''));
const pick = (...vals) => vals.map(clean).find((v) => v && !isTemplate(v)) || '';

const TRACKING = /^(utm_|fbclid|gclid|igshid|mc_|ref$|referrer$|_branch|campaign|adset|ad_id|af_)/i;
const cleanUrl = (url) => {
  const x = parseUrl(String(url || '').replace(/^http:\/\//i, 'https://'));
  if (!x) return String(url || '');
  const kept = x.pairs.filter(([k]) => !TRACKING.test(k)).map((p) => p[2]);
  return `${x.origin}${x.pathname}${kept.length ? `?${kept.join('&')}` : ''}`;
};

// Meta CDN video urls carry base64 JSON in `efg` with the asset id and duration.
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const b64decode = (str) => {
  let bits = 0; let val = 0; let out = '';
  for (const ch of str.replace(/-/g, '+').replace(/_/g, '/').replace(/[^A-Za-z0-9+/]/g, '')) {
    val = ((val << 6) | B64.indexOf(ch)) & 0xffffff; bits += 6;
    if (bits >= 8) { bits -= 8; out += String.fromCharCode((val >> bits) & 255); }
  }
  return out;
};
const decodeEfg = (url) => {
  try {
    const x = parseUrl(url);
    const efg = x && x.get('efg');
    if (!efg) return {};
    const j = JSON.parse(b64decode(efg));
    return { assetId: j.xpv_asset_id ? String(j.xpv_asset_id) : null, durationS: j.duration_s ?? null };
  } catch (e) { return {}; }
};

const SCRIPTS = [
  [/[஀-௿]/, 'Tamil'], [/[ಀ-೿]/, 'Kannada'], [/[ఀ-౿]/, 'Telugu'],
  [/[ഀ-ൿ]/, 'Malayalam'], [/[ঀ-৿]/, 'Bengali'], [/[઀-૿]/, 'Gujarati'],
  [/[਀-੿]/, 'Punjabi'], [/[଀-୿]/, 'Odia'], [/[ऀ-ॿ]/, 'Hindi'],
];
const HINGLISH = /\b(karo|kare|karein|sirf|mein|hai|hain|se|shuru|aap|apni|apna|bolo|seekho|sikho|kya|nahi|abhi|ab)\b/i;
const detectLanguage = (text) => {
  const hit = SCRIPTS.find(([re]) => re.test(text));
  if (hit) return hit[1];
  if (HINGLISH.test(text)) return 'Hinglish';
  return text ? 'English' : 'Unknown';
};

const hash = (s) => {
  let h = 5381;
  for (const ch of String(s)) h = ((h << 5) + h + ch.codePointAt(0)) >>> 0;
  return h.toString(36);
};
const copyKey = (s) => String(s).toLowerCase().replace(/#\w+/g, '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

// Node 04 returns the whole Apify response as one text item, so the success
// path always runs exactly once (empty list and actor errors included).
const rows = [];
$input.all().forEach(({ json: j }) => {
  if (typeof j.raw === 'string') {
    try { const p = JSON.parse(j.raw); rows.push(...(Array.isArray(p) ? p : [p])); } catch (e) { rows.push({ error: 'Scraper returned non-JSON output' }); }
  } else rows.push(j);
});
const scraperError = (rows.find((j) => j && j.error) || {}).error || null;
const rawItems = rows.filter((j) => j && (j.ad_archive_id || j.adArchiveID || j.adArchiveId || j.adId));

const nowMs = Date.now();
const seenIds = new Set();
const seenAssets = new Map();
const ads = [];
const duplicates = [];
let reportedTotal = null;

rawItems.forEach((r, idx) => {
  const s = r.snapshot || r.adSnapshot || {};
  const cards = Array.isArray(s.cards) ? s.cards : [];
  const firstCard = cards[0] || {};
  const adId = String(r.ad_archive_id || r.adArchiveID || r.adArchiveId || r.adId);
  if (Number.isFinite(r.total)) reportedTotal = Math.max(reportedTotal || 0, r.total);

  const videos = [...(s.videos || []), ...cards.filter((c) => c.video_sd_url || c.video_hd_url)];
  const images = [...(s.images || []), ...cards.filter((c) => c.original_image_url || c.resized_image_url)];
  const v0 = videos[0];
  const videoUrl = v0 ? (v0.video_sd_url || v0.video_hd_url) : (r.videoUrl || '');
  const imageUrl = (v0 && v0.video_preview_image_url) || (images[0] && (images[0].original_image_url || images[0].resized_image_url)) || r.imageUrl || '';
  const assetIds = [...new Set(videos.map((v) => decodeEfg(v.video_sd_url || v.video_hd_url).assetId).filter(Boolean))].sort();
  const durationS = videoUrl ? (decodeEfg(videoUrl).durationS ?? null) : null;

  const headline = pick(s.title, firstCard.title, r.title, r.headline);
  const body = pick(s.body, firstCard.body, r.body, r.adText, r.primaryText);
  const linkDescription = pick(s.link_description, firstCard.link_description);
  const cta = pick(s.cta_text, firstCard.cta_text, r.ctaText, r.cta) || 'None';
  const templateLeak = [s.title, s.body && s.body.text, s.link_description].some(isTemplate);
  const hashtags = (body.match(/#[\p{L}\p{N}_]+/gu) || []);
  const bodyNoTags = clean(body.replace(/#[\p{L}\p{N}_]+/gu, ' ')).replace(/ +\n/g, '\n').replace(/\n +/g, '\n');

  const startSec = r.start_date || (r.startDate ? Date.parse(r.startDate) / 1000 : null)
    || (r.start_date_formatted ? Date.parse(r.start_date_formatted.replace(' ', 'T') + 'Z') / 1000 : null);
  const daysActive = startSec ? Math.max(0, Math.round((nowMs - startSec * 1000) / 86400000)) : null;
  const platforms = (r.publisher_platform || r.publisherPlatform || r.platforms || []).map((x) => String(x).toLowerCase());
  const linkUrl = cleanUrl(s.link_url || firstCard.link_url || r.linkUrl);

  // Exact duplicates: same ad id, or the exact same set of creative assets.
  const assetKey = assetIds.join('|');
  if (seenIds.has(adId)) { duplicates.push({ adId, reason: 'same ad id' }); return; }
  if (assetKey && seenAssets.has(assetKey)) { duplicates.push({ adId, reason: 'same creative assets', duplicateOf: seenAssets.get(assetKey) }); return; }
  seenIds.add(adId);
  if (assetKey) seenAssets.set(assetKey, adId);

  ads.push({
    adId,
    pageName: clean(r.page_name || s.page_name || r.pageName),
    pageId: String(r.page_id || s.page_id || r.pageId || ''),
    adLibraryUrl: r.ad_library_url || `https://www.facebook.com/ads/library/?id=${adId}`,
    libraryPosition: Number(r.position) || idx + 1,
    startDate: startSec ? new Date(startSec * 1000).toISOString().slice(0, 10) : null,
    daysActive,
    platforms,
    displayFormat: s.display_format || r.displayFormat || '',
    variantCount: Math.max(cards.length, videos.length, images.length, 1),
    mediaType: videoUrl ? 'video' : imageUrl ? 'image' : 'text',
    videoUrl,
    imageUrl,
    assetIds,
    durationS,
    headline,
    body: bodyNoTags,
    hashtags,
    linkDescription,
    linkUrl,
    linkDomain: ((parseUrl(linkUrl) || {}).hostname || '').replace(/^www\./, ''),
    cta,
    language: detectLanguage(`${headline} ${body}`),
    templateLeak,
    copyFingerprint: hash(copyKey(`${headline}|${bodyNoTags}`)),
    rawData: r,
  });
});

if (!ads.length) {
  return [{ json: { noAds: true, message: 'No ads were found for this query.', scraperError, scrapedRows: rawItems.length } }];
}

const sample = ads.slice(0, cfg.maxAds);
const copyGroups = {};
sample.forEach((a) => { copyGroups[a.copyFingerprint] = (copyGroups[a.copyFingerprint] || 0) + 1; });
sample.forEach((a) => { a.copyGroupSize = copyGroups[a.copyFingerprint]; a.sameCopy = a.copyGroupSize > 1; });

const uniq = (arr) => [...new Set(arr.filter(Boolean))];
const portfolio = {
  scrapedRows: rawItems.length,
  duplicatesRemoved: duplicates.length,
  duplicates,
  sampleSize: sample.length,
  reportedActiveAds: reportedTotal,
  pages: uniq(sample.map((a) => a.pageName)),
  uniqueCaptions: Object.keys(copyGroups).length,
  uniqueCreatives: uniq(sample.map((a) => a.assetIds.join('|') || a.videoUrl || a.imageUrl || a.adId)).length,
  mediaMix: sample.reduce((m, a) => ({ ...m, [a.mediaType]: (m[a.mediaType] || 0) + 1 }), {}),
  dcoShare: sample.filter((a) => a.displayFormat === 'DCO').length,
  templateLeaks: sample.filter((a) => a.templateLeak).map((a) => a.adId),
  captionLanguages: uniq(sample.map((a) => a.language)),
  platforms: uniq(sample.flatMap((a) => a.platforms)),
  destinations: sample.reduce((m, a) => ({ ...m, [a.linkDomain || 'none']: (m[a.linkDomain || 'none'] || 0) + 1 }), {}),
  ctaButtons: uniq(sample.map((a) => a.cta)),
  oldestStart: sample.map((a) => a.startDate).filter(Boolean).sort()[0] || null,
  newestStart: sample.map((a) => a.startDate).filter(Boolean).sort().slice(-1)[0] || null,
};

return sample.map((a, i) => ({ json: { ...a, sampleIndex: i + 1, portfolio } }));

// Deterministic scoring. Gemini only supplies 0-10 sub-scores and flags;
// every weight, rank and gap below is computed here so the same inputs
// always produce the same winner.
const CREATIVE_WEIGHTS = {
  hookScore: 0.20, clarityScore: 0.15, valuePropScore: 0.15, offerScore: 0.15,
  ctaScore: 0.10, specificityScore: 0.10, creativeAngleScore: 0.10, conversionIntentScore: 0.05,
};
const MARKET_WEIGHTS = { impressionRank: 0.5, longevity: 0.3, distribution: 0.2 };
const BLEND = { creative: 0.7, market: 0.3 };
const LONGEVITY_FULL_DAYS = 30;

const cfg = $('02 — Validate & Parse URL').first().json;
const portfolio = $('05 — Normalize, Clean & Fingerprint').first().json.portfolio;
const all = $input.all().map((i) => i.json);
const scored = all.filter((a) => a.analysis);
const unscored = all.filter((a) => !a.analysis).map((a) => ({ adId: a.adId, reason: a.aiError || 'analysis failed' }));
const N = scored.length;

const r1 = (x) => (x == null ? null : Math.round(x * 10) / 10);
const median = (xs) => {
  const v = xs.filter((x) => x != null).sort((a, b) => a - b);
  if (!v.length) return null;
  const m = Math.floor(v.length / 2);
  return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2;
};
const avg = (xs) => { const v = xs.filter((x) => x != null); return v.length ? v.reduce((s, x) => s + x, 0) / v.length : null; };
const countBy = (xs) => xs.reduce((m, x) => { const k = x || 'n/a'; m[k] = (m[k] || 0) + 1; return m; }, {});
const sortedCounts = (obj) => Object.entries(obj).sort((a, b) => b[1] - a[1]).map(([label, count]) => ({ label, count, share: N ? Math.round((count / N) * 100) : 0 }));
const norm = (s) => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const primaryLanguage = (l) => String(l || 'n/a').split(/[,(/&]| and /)[0].trim() || 'n/a';
const offerLabel = (o) => {
  const t = String(o || '');
  if (/^(none|not observed)/i.test(t)) return 'No offer shown';
  const price = t.match(/(₹|rs\.?|inr)\s?\d+/i);
  return price ? `${price[0].replace(/\s+/g, '').replace(/^(rs\.?|inr)/i, '₹')} entry offer` : t.slice(0, 40);
};

// 1) Creative score (0-100) from the rubric.
scored.forEach((a) => {
  const s = a.analysis.scores;
  let total = 0;
  const imputed = [];
  Object.entries(CREATIVE_WEIGHTS).forEach(([k, w]) => {
    let v = s[k];
    if (v == null) { v = 5; imputed.push(k); }
    total += v * w * 10;
  });
  a.creativeScore = r1(total);
  a.imputedScores = imputed;
});

// 2) Creative clones: the same video re-uploaded under another ad id. Only ads
//    whose video was actually watched are compared. Two match when durations are
//    equal and the opening line agrees in the original language or in English
//    (Gemini's transliteration varies).
const lineKey = (t) => { const k = norm(t).slice(0, 16); return k && k !== 'not observed' ? k : null; };
const parent = Object.fromEntries(scored.map((a) => [a.adId, a.adId]));
const root = (id) => (parent[id] === id ? id : (parent[id] = root(parent[id])));
scored.forEach((a, i) => scored.slice(i + 1).forEach((b) => {
  if (a.analysisMode !== 'watched video' || b.analysisMode !== 'watched video') return;
  if (a.durationS == null || a.durationS !== b.durationS) return;
  const sameLine = [['text', 'text'], ['english', 'english']].some(([x, y]) => {
    const ka = lineKey(a.analysis.hook[x]); return ka && ka === lineKey(b.analysis.hook[y]);
  });
  if (sameLine) parent[root(b.adId)] = root(a.adId);
}));
const cloneGroups = {};
scored.forEach((a) => { (cloneGroups[root(a.adId)] = cloneGroups[root(a.adId)] || []).push(a.adId); });
scored.forEach((a) => {
  const g = cloneGroups[root(a.adId)];
  a.cloneCount = g.length;
  a.cloneOf = g.filter((id) => id !== a.adId);
});

// 3) Market signal (0-100) from observable Ad Library behaviour only.
const byPosition = [...scored].sort((x, y) => x.libraryPosition - y.libraryPosition);
byPosition.forEach((a, idx) => {
  const parts = {};
  if (cfg.impressionSorted) parts.impressionRank = N > 1 ? (100 * (N - 1 - idx)) / (N - 1) : 100;
  if (a.daysActive != null) parts.longevity = Math.min(a.daysActive / LONGEVITY_FULL_DAYS, 1) * 100;
  parts.distribution = Math.min((a.platforms.length || 1) / 5, 1) * 60 + Math.min(a.cloneCount - 1, 2) * 20;
  const wSum = Object.keys(parts).reduce((s, k) => s + MARKET_WEIGHTS[k], 0);
  a.marketParts = Object.fromEntries(Object.entries(parts).map(([k, v]) => [k, r1(v)]));
  a.marketSignal = r1(Object.entries(parts).reduce((s, [k, v]) => s + v * MARKET_WEIGHTS[k], 0) / wSum);
  a.impressionRankInSample = idx + 1;
});

// 4) Blend, rank, quadrant.
scored.forEach((a) => { a.adStrengthIndex = r1(a.creativeScore * BLEND.creative + a.marketSignal * BLEND.market); });
scored.sort((x, y) => (y.adStrengthIndex - x.adStrengthIndex) || (y.creativeScore - x.creativeScore) || (x.libraryPosition - y.libraryPosition));
const medC = median(scored.map((a) => a.creativeScore));
const medM = median(scored.map((a) => a.marketSignal));
scored.forEach((a, i) => {
  a.rank = i + 1;
  const hiC = a.creativeScore >= medC;
  const hiM = a.marketSignal >= medM;
  a.quadrant = hiC && hiM ? 'Proven winner' : hiC ? 'Hidden gem' : hiM ? 'Study this' : 'Retire';
});

// 5) Patterns across the sample.
const A = (a) => a.analysis;
const dims = Object.keys(CREATIVE_WEIGHTS);
const aggregates = {
  n: N,
  avgCreative: r1(avg(scored.map((a) => a.creativeScore))),
  avgMarket: r1(avg(scored.map((a) => a.marketSignal))),
  avgDims: Object.fromEntries(dims.map((k) => [k, r1(avg(scored.map((a) => A(a).scores[k])))])),
  hookTypes: sortedCounts(countBy(scored.map((a) => A(a).hook.type))),
  formats: sortedCounts(countBy(scored.map((a) => A(a).format))),
  talent: sortedCounts(countBy(scored.map((a) => A(a).talent))),
  spokenLanguages: sortedCounts(countBy(scored.map((a) => primaryLanguage(A(a).language)))),
  angles: sortedCounts(countBy(scored.map((a) => A(a).creativeAngle))),
  awareness: sortedCounts(countBy(scored.map((a) => A(a).awarenessLevel))),
  funnel: sortedCounts(countBy(scored.map((a) => A(a).funnelStage))),
  ctaButtons: sortedCounts(countBy(scored.map((a) => a.cta))),
  spokenCtaNone: scored.filter((a) => /^(none|not observed)/i.test(A(a).cta.spoken)).length,
  offers: sortedCounts(countBy(scored.map((a) => offerLabel(A(a).offer)))),
  medianProductSec: median(scored.map((a) => A(a).productFirstSeenSec)),
  medianBrandSec: median(scored.map((a) => A(a).brandFirstMentionSec)),
  captionsShare: N ? Math.round((scored.filter((a) => A(a).captionsBurnedIn).length / N) * 100) : 0,
  flags: Object.fromEntries(Object.keys(scored[0] ? A(scored[0]).flags : {}).map((k) => [k, scored.filter((a) => A(a).flags[k]).length])),
  medianDuration: median(scored.map((a) => a.durationS)),
  cloneGroups: Object.values(cloneGroups).filter((g) => g.length > 1),
  quadrants: sortedCounts(countBy(scored.map((a) => a.quadrant))),
  analysisModes: sortedCounts(countBy(scored.map((a) => a.analysisMode))),
};

// 6) Gap candidates - counted, never guessed. The strategist may only build on these.
const FLAG_LABEL = {
  quantifiedOutcome: 'a quantified outcome (a number, a timeline, a salary or score jump)',
  socialProof: 'social proof (learner counts, ratings, testimonials)',
  urgency: 'urgency or a deadline',
  comparison: 'a comparison against the alternative (tutor, coaching class, YouTube)',
  objectionHandling: 'objection handling (shy, no time, weak grammar, too old)',
  beforeAfter: 'a before -> after transformation',
  customerStory: 'a real learner story',
  priceShown: 'the price inside the creative itself',
};
const gaps = [];
Object.entries(FLAG_LABEL).forEach(([k, label]) => {
  const c = aggregates.flags[k] || 0;
  if (N && c / N <= 0.25) gaps.push({ key: k, severity: 1 - c / N, title: c ? `Only ${c} of ${N} ads use ${label}` : `None of the ${N} ads use ${label}`, count: c, n: N, examples: scored.filter((a) => A(a).flags[k]).map((a) => a.adId) });
});
const topHook = aggregates.hookTypes[0];
if (topHook && topHook.share >= 50) gaps.push({ key: 'hookMonoculture', severity: topHook.share / 100, title: `${topHook.share}% of hooks are the same type (${topHook.label})`, count: topHook.count, n: N });
if (aggregates.ctaButtons.length === 1) gaps.push({ key: 'ctaMonoculture', severity: 0.7, title: `All ${N} ads end on the same button: "${aggregates.ctaButtons[0].label}"`, count: N, n: N });
if (aggregates.spokenCtaNone >= N / 2) gaps.push({ key: 'silentCta', severity: aggregates.spokenCtaNone / N, title: `${aggregates.spokenCtaNone} of ${N} creatives never say or show what to do next`, count: aggregates.spokenCtaNone, n: N });
const topOffer = aggregates.offers[0];
if (topOffer && N > 2 && topOffer.share >= 80) gaps.push({ key: 'offerMonoculture', severity: 0.6, title: `${topOffer.count} of ${N} ads lean on one offer ("${topOffer.label}") with no offer ladder`, count: topOffer.count, n: N });
if (aggregates.medianProductSec != null && aggregates.medianProductSec > 6) gaps.push({ key: 'lateProduct', severity: Math.min(aggregates.medianProductSec / 20, 1), title: `The product shows up late: median first appearance at ${aggregates.medianProductSec}s`, count: null, n: N });
if (aggregates.captionsShare < 50) gaps.push({ key: 'soundOff', severity: 1 - aggregates.captionsShare / 100, title: `Only ${aggregates.captionsShare}% of creatives work with the sound off`, count: null, n: N });
if (cfg.country === 'IN') {
  const seen = new Set([...portfolio.captionLanguages, ...aggregates.spokenLanguages.map((l) => l.label)].join(' ').match(/Hindi|Hinglish|Tamil|Kannada|Telugu|Bengali|Marathi|Malayalam|Gujarati|Punjabi|Odia/g) || []);
  const missing = ['Telugu', 'Bengali', 'Marathi', 'Malayalam', 'Gujarati'].filter((l) => !seen.has(l));
  if (missing.length >= 3) gaps.push({ key: 'languageCoverage', severity: 0.5, title: `Sample covers ${[...seen].join(', ') || 'no regional language'}; nothing in ${missing.slice(0, 3).join(', ')}`, count: seen.size, n: N, note: 'Within the sampled top ads only - the full library may differ.' });
}
gaps.sort((a, b) => b.severity - a.severity);

// 7) Brief for the strategist (compact, evidence-first).
const winner = scored[0];
const line = (a) => {
  const x = A(a);
  const flags = Object.entries(x.flags).filter(([, v]) => v).map(([k]) => k).join(',') || 'none';
  return `#${a.rank} ad ${a.adId} | index ${a.adStrengthIndex} (creative ${a.creativeScore}, market ${a.marketSignal}, ${a.quadrant}) | ${x.format}, ${x.language}, ${a.durationS || '?'}s | hook[${x.hook.type}, ${x.scores.hookScore}/10]: "${x.hook.english}" | angle: ${x.creativeAngle} | offer: ${x.offer} | spoken CTA: ${x.cta.spoken} | product at ${x.productFirstSeenSec ?? '?'}s | flags: ${flags} | weakness: ${x.weakness}`;
};
const strategistPrompt = [
  `ADVERTISER: ${cfg.brand} | Market: ${cfg.country} | Source: Meta Ad Library, ${cfg.activeStatus} ads, sorted by ${cfg.sortMode}.`,
  `PORTFOLIO (observed): ${portfolio.reportedActiveAds ?? 'unknown'} active ads reported by the library; sample ${N}; ${portfolio.pages.length} Facebook pages in sample (${portfolio.pages.join('; ')}); ${portfolio.uniqueCreatives} unique creatives but only ${portfolio.uniqueCaptions} unique captions; ${portfolio.dcoShare}/${portfolio.sampleSize} are Dynamic Creative; caption languages: ${portfolio.captionLanguages.join(', ')}; destinations: ${JSON.stringify(portfolio.destinations)}; template placeholders leaking in ${portfolio.templateLeaks.length} ads.`,
  `AGGREGATES: avg creative ${aggregates.avgCreative}, avg market ${aggregates.avgMarket}; hook types ${JSON.stringify(aggregates.hookTypes.map((h) => `${h.label}:${h.count}`))}; formats ${JSON.stringify(aggregates.formats.map((h) => `${h.label}:${h.count}`))}; median product reveal ${aggregates.medianProductSec}s; sound-off ready ${aggregates.captionsShare}%; flags ${JSON.stringify(aggregates.flags)}; creative clones ${JSON.stringify(aggregates.cloneGroups)}.`,
  'RANKED ADS:',
  ...scored.map(line),
  `WINNER DETAIL: ${JSON.stringify({ adId: winner && winner.adId, observed: winner && A(winner).observed, whyItWorks: winner && A(winner).whyItWorks, first3s: winner && A(winner).first3s, scores: winner && A(winner).scores })}`,
  'GAP CANDIDATES (counted from the data, ordered by severity):',
  ...gaps.map((g, i) => `${i + 1}. ${g.title}${g.note ? ` (${g.note})` : ''}`),
].join('\n');

return [{
  json: {
    config: cfg,
    portfolio,
    weights: { creative: CREATIVE_WEIGHTS, market: MARKET_WEIGHTS, blend: BLEND, longevityFullDays: LONGEVITY_FULL_DAYS },
    ads: scored,
    unscored,
    winner,
    aggregates,
    gaps,
    medians: { creative: medC, market: medM },
    strategistPrompt,
  },
}];

// Parse the strategist memo. If Gemini is down or returns junk the report
// still ships: every section falls back to the deterministic findings.
const base = $('14 — Score, Rank & Find Gaps').first().json;

const collectText = (node) => {
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(collectText).join('');
  if (typeof node === 'object') {
    if (typeof node.text === 'string') return node.text;
    for (const k of ['content', 'parts', 'message', 'output']) if (node[k]) return collectText(node[k]);
    if (node.candidates) return collectText(node.candidates[0]);
  }
  return '';
};
const parseJson = (text) => {
  let t = String(text || '').replace(/```(?:json)?/gi, '').trim();
  const s = t.indexOf('{');
  const e = t.lastIndexOf('}');
  if (s === -1 || e <= s) throw new Error('No JSON in strategist output');
  t = t.slice(s, e + 1);
  try { return JSON.parse(t); } catch (err) { return JSON.parse(t.replace(/,\s*([}\]])/g, '$1')); }
};

// Belt and braces: scrub the phrases that make copy read machine-written.
const BANNED = /\b(leverag\w*|unlock\w*|elevat\w*|robust|seamless\w*|delv\w*|game[- ]changer|cutting[- ]edge|landscape|resonat\w*|crucial|harness\w*|tapestry|synerg\w*|revolutioni[sz]\w*|empower\w*|holistic|comprehensive)\b/gi;
const SWAP = { leverage: 'use', unlock: 'open up', elevate: 'lift', robust: 'solid', seamless: 'smooth', crucial: 'key', resonate: 'land', harness: 'use', comprehensive: 'full', holistic: 'whole' };
const scrub = (v) => {
  if (typeof v === 'string') {
    return v.replace(BANNED, (m) => {
      const stem = Object.keys(SWAP).find((k) => m.toLowerCase().startsWith(k.slice(0, -1)));
      return stem ? SWAP[stem] : '';
    }).replace(/\s{2,}/g, ' ').replace(/!+/g, '.').trim();
  }
  if (Array.isArray(v)) return v.map(scrub);
  if (v && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, scrub(x)]));
  return v;
};
const arr = (v) => (Array.isArray(v) ? v : []);

let strategy = null;
let strategyError = null;
try {
  const p = parseJson(collectText($input.first().json));
  if (!p.headline || !Array.isArray(p.concepts)) throw new Error('Strategist JSON missing headline/concepts');
  strategy = scrub(p);
} catch (e) {
  strategyError = $input.first().json.error ? String($input.first().json.error.message || $input.first().json.error) : e.message;
}

const w = base.winner;
const fallback = {
  headline: `${base.config.brand}: ${base.portfolio.uniqueCreatives} distinct creatives behind ${base.portfolio.uniqueCaptions} captions in the sampled top ads.`,
  executiveSummary: [
    w ? `Top-scoring ad ${w.adId} reached ${w.adStrengthIndex}/100 on the Ad Strength Index.` : 'No ad could be scored.',
    `Average creative score across ${base.aggregates.n} ads: ${base.aggregates.avgCreative}/100.`,
    base.aggregates.hookTypes[0] ? `Most common hook type: ${base.aggregates.hookTypes[0].label} (${base.aggregates.hookTypes[0].count} ads).` : '',
  ].filter(Boolean),
  winnerWhy: w ? [{ point: 'Highest blended score', evidence: w.analysis.whyItWorks }] : [],
  winnerSteal: [],
  hookTakeaway: '', ctaTakeaway: '',
  patterns: [],
  gaps: base.gaps.slice(0, 5).map((g) => ({ title: g.title, evidence: `${g.count ?? '-'} of ${g.n}`, whyItMatters: '', opportunity: '' })),
  concepts: [],
  recommendations: [],
};

const s = strategy || fallback;
return [{
  json: {
    ...base,
    strategy: {
      ...s,
      executiveSummary: arr(s.executiveSummary).slice(0, 4),
      winnerWhy: arr(s.winnerWhy).slice(0, 5),
      patterns: arr(s.patterns).slice(0, 5),
      gaps: arr(s.gaps).slice(0, 5),
      concepts: arr(s.concepts).slice(0, 3),
      recommendations: arr(s.recommendations).slice(0, 6),
    },
    strategySource: strategy ? 'gemini' : 'deterministic fallback',
    strategyError,
  },
}];

// Renders the final report as print-ready HTML (A4). Same file feeds PDF.co
