  return `<svg viewBox="0 0 ${W} ${H}" class="scatter">
    <line x1="${x(mc)}" y1="10" x2="${x(mc)}" y2="${H - P}" class="med"/><line x1="${P}" y1="${y(mm)}" x2="${W - 10}" y2="${y(mm)}" class="med"/>
